def page(content,title=None):
    h=HEAD if title is None else HEAD.replace('Regan Yates | Technology Leadership &amp; Architecture',title)
    return '<!doctype html><html lang="en">'+h+'<body class="bg-surface font-body-md text-on-surface antialiased">'+HEADER+'<main id="main">'+content+'</main>'+FOOTER+'<script src="/site.js" defer></script></body></html>'
def section(content,extra='',tone='bg-surface'):
    return f'<section class="w-full px-margin md:px-margin-tablet lg:px-margin-desktop py-space-xl {tone}" {extra}><div class="max-w-7xl mx-auto">{content}</div></section>'
def brief(label,text,tone='bg-surface-container-low'):
    return f'<div class="p-space-md {tone} flex flex-col gap-space-sm"><h3 class="label">{label}</h3><p class="body-copy">{text}</p></div>'
HERO=section('''<div class="hero-layout"><div><p class="technical bronze">TECHNOLOGY LEADERSHIP // ARCHITECTURE &amp; AUTOMATION</p><h1 class="font-display-lg text-display-lg text-primary tracking-tight mt-3">Technical Decisions.<br>People. Business Impact.</h1><p class="hero-subtitle">Building systems with the bigger picture in mind.</p></div><aside class="p-space-md bg-surface-container-low"><span class="label">A practical perspective</span><p class="body-copy mt-2">I’m Regan Yates. I bring hands-on development and enterprise IT experience to improving systems, guiding technology decisions, and leading people.</p></aside></div><div class="taxonomy" id="work"><span class="label">Explore the work</span><div id="taxonomy-filters" role="group" aria-label="Filter selected work"><button type="button" data-filter="all" aria-pressed="true">All Work [03]</button><button type="button" data-filter="architecture" aria-pressed="false">Architecture</button><button type="button" data-filter="automation" aria-pressed="false">AI &amp; Automation</button></div><span class="technical filter-count" role="status" aria-live="polite">3 projects shown</span></div>''')
ONE=section('''<div class="case-strip"><div><span class="case-badge">PROJECT 01 / ONEGAUGE</span><span>AUTOMOTIVE TECHNOLOGY</span></div><span>APR 2026 – PRESENT // IN DEVELOPMENT</span></div><div class="grid grid-cols-1 lg:grid-cols-12 gap-gutter-desktop"><div class="lg:col-span-5 flex flex-col gap-space-lg"><div><h2 class="font-headline-xl text-headline-xl text-primary leading-tight">From Custom Firmware to a Configurable Platform</h2><p class="font-body-lg text-body-lg text-secondary mt-3">Helping shape the software direction for digital motorsports gauge systems.</p></div>'''+brief('The product challenge','Specialized vehicles and configurations require tailored firmware. The next step is a more scalable platform that gives customers greater control over configuration and vehicle-data visualization.','bg-surface-container')+brief('My role in the direction','As Technical Lead &amp; Developer, I lead software technology decisions, including tooling, architecture, and project-management systems. I develop embedded firmware and a customer-facing application intended to support self-service configuration.')+'''<div class="chips"><span>Embedded firmware</span><span>Software architecture</span><span>Product direction</span></div></div><div class="lg:col-span-7 flex flex-col gap-space-md"><div class="blueprint-board"><div class="board-heading"><span>FIG 1.1 / PRODUCT DIRECTION</span><span>CONCEPTUAL PROGRESSION</span></div><div class="blueprint"><div class="nodes"><div class="node"><span class="node-index">01</span><strong>Vehicle needs</strong><span>Specialized configurations</span></div><div class="node"><span class="node-index">02</span><strong>Gauge firmware</strong><span>Custom embedded behavior</span></div><div class="node"><span class="node-index">03</span><strong>Customer application</strong><span>Self-service configuration</span></div></div><div class="flowline" aria-hidden="true"><span>REQUIREMENTS</span><i></i><span>FIRMWARE</span><i></i><span>PLATFORM</span></div><div class="system-notes">[DIRECTION] Move toward a user-configurable platform.<br>[OWNERSHIP] Connect architecture and hands-on development.<br>[STATUS] Application and platform work are ongoing.</div></div><p class="board-caption">A summary of the product direction, not a deployed system architecture.</p></div><div class="metric-panel"><p class="label">Areas of ownership</p><div class="metric-grid"><div><strong>Direction</strong><span>Tooling &amp; architecture decisions</span></div><div><strong>Delivery</strong><span>Embedded firmware development</span></div><div><strong>Platform</strong><span>Customer application development</span></div></div></div></div></div>''','data-category="architecture" data-project="OneGauge"','bg-surface-container-lowest')
PROJECTS=section('''<p class="label bronze">Applied AI &amp; Systems Thinking</p><h2 class="section-title">Projects Built Around Real Workflows</h2><p class="body-copy max-w-3xl">Personal projects exploring how software can help people navigate information and automate everyday work.</p><div class="project-cards"><article class="project-card" data-category="automation" data-project="Luther"><span class="technical bronze">PROJECT 02 // RESEARCH TOOL BUILT</span><h3>Luther / Medieval History Research</h3><p>Built around a doctoral researcher’s workflow, Luther aggregates medieval-history journal content, summarizes articles and issues, and surfaces potential gaps and underexplored research questions.</p><div class="card-note">FOCUS: Bring content discovery and research exploration into a workflow shaped around its user.</div><div class="card-bottom">PERSONAL PROJECT · RESEARCH &amp; APPLIED AI</div></article><article class="project-card" data-category="architecture automation" data-project="Vera"><span class="technical bronze">PROJECT 03 // IN DESIGN &amp; DEVELOPMENT</span><h3>Vera / Local-First Automation</h3><p>I’m designing a self-hosted personal automation platform centered on local infrastructure, service integrations, and workflows, with explicit human approval for consequential external actions.</p><div class="card-note">FOCUS: Connect services while making system ownership and human oversight part of the design.</div><div class="card-bottom">PERSONAL PROJECT · SYSTEMS &amp; AUTOMATION</div></article></div>''','id="projects"','bg-surface-container-low')
